<?php
require_once "config.php"; require_login();
$eventsTotal=(int)$conn->query("SELECT COUNT(*) n FROM events")->fetch_assoc()['n'];
$regsTotal=(int)$conn->query("SELECT COUNT(*) n FROM registrations")->fetch_assoc()['n'];
$upcoming=(int)$conn->query("SELECT COUNT(*) n FROM events WHERE event_date>=CURDATE()")->fetch_assoc()['n'];
$capacity=(int)$conn->query("SELECT COALESCE(SUM(capacity),0) n FROM events WHERE event_date>=CURDATE()")->fetch_assoc()['n'];
$booked=(int)$conn->query("SELECT COUNT(*) n FROM registrations r JOIN events e ON e.id=r.event_id WHERE e.event_date>=CURDATE()")->fetch_assoc()['n'];
$fill=$capacity>0?min(100,round($booked/$capacity*100)):0;
$catRows=$conn->query("SELECT category,COUNT(*) total FROM events GROUP BY category ORDER BY total DESC");$cats=[];while($r=$catRows->fetch_assoc())$cats[]=$r;
$monthly=$conn->query("SELECT DATE_FORMAT(registered_at,'%b %Y') label,COUNT(*) total,DATE_FORMAT(registered_at,'%Y-%m') sortkey FROM registrations WHERE registered_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY sortkey,label ORDER BY sortkey");$months=[];while($r=$monthly->fetch_assoc())$months[]=$r;
$popular=$conn->query("SELECT e.title,e.category,e.event_date,e.capacity,COUNT(r.id) total FROM events e LEFT JOIN registrations r ON r.event_id=e.id GROUP BY e.id ORDER BY total DESC,e.event_date ASC LIMIT 5");
include "partials_header.php";
?>
