<div class="stat-card" style="--wash:#e9e1ff"><div class="stat-top"><span class="stat-icon violet">✦</span><span class="muted">01</span></div><p>Total events</p><strong><?=$eventsTotal?></strong><small>Across all categories</small></div>
<div class="stat-card" style="--wash:#dceaff"><div class="stat-top"><span class="stat-icon blue">▦</span><span class="muted">02</span></div><p>Total registrations</p><strong><?=$regsTotal?></strong><small>All-time sign-ups</small></div>
<div class="stat-card" style="--wash:#d9f8ea"><div class="stat-top"><span class="stat-icon green">◷</span><span class="muted">03</span></div><p>Upcoming events</p><strong><?=$upcoming?></strong><small>Scheduled from today</small></div>
