<section class="analytics-card"><div class="section-heading"><div><h2>Most popular events</h2><p>Ranked by participant registrations</p></div><a class="text-link" href="events.php">Manage events →</a></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Event</th><th>Category</th><th>Date</th><th>Registrations</th><th>Capacity used</th></tr></thead><tbody><?php $rank=0;if($popular->num_rows):while($r=$popular->fetch_assoc()):$rank++;$pct=(int)$r['capacity']>0?min(100,round((int)$r['total']/(int)$r['capacity']*100)):0;?><tr><td><span class="count-pill">#<?=$rank?></span></td><td><strong><?=e($r['title'])?></strong></td><td><?=e($r['category'])?></td><td><?=e(date('d M Y',strtotime($r['event_date'])))?></td><td><strong><?=(int)$r['total']?></strong></td><td><div style="display:flex;align-items:center;gap:10px;min-width:100px"><div class="capacity-track" style="flex:1"><span style="width:<?=$pct?>%"></span></div><small><?=$pct?>%</small></div></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty">Create events and register participants to unlock insights.</td></tr><?php endif;?></tbody></table></div></section>
<script>
const monthlyLabels=<?=json_encode(array_column($months,'label'),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;
const monthlyValues=<?=json_encode(array_map('intval',array_column($months,'total')))?>;
const categoryLabels=<?=json_encode(array_column($cats,'category'),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;
const categoryValues=<?=json_encode(array_map('intval',array_column($cats,'total')))?>;
function drawBarChart(id,labels,values){const c=document.getElementById(id),ctx=c.getContext('2d');const dpr=window.devicePixelRatio||1;const w=c.clientWidth,h=c.clientHeight;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);const pad={l:30,r:12,t:18,b:38},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b;ctx.font='11px Arial';ctx.strokeStyle='#e9eaf5';ctx.fillStyle='#8589a6';ctx.lineWidth=1;const max=Math.max(4,...values);for(let i=0;i<5;i++){let y=pad.t+ch*i/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText(Math.round(max*(4-i)/4),2,y+4)}const step=cw/Math.max(labels.length,1),bw=Math.min(32,step*.55);values.forEach((v,i)=>{let bh=v/max*(ch-5),x=pad.l+i*step+(step-bw)/2,y=pad.t+ch-bh;let g=ctx.createLinearGradient(0,y,0,y+bh);g.addColorStop(0,'#9278ff');g.addColorStop(1,'#557df7');ctx.fillStyle=g;ctx.beginPath();ctx.roundRect?ctx.roundRect(x,y,bw,bh,[6,6,2,2]):ctx.rect(x,y,bw,bh);ctx.fill();ctx.fillStyle='#747895';ctx.textAlign='center';ctx.fillText(String(labels[i]||'').slice(0,9),x+bw/2,h-12);});}
function drawDonut(id,labels,values){const c=document.getElementById(id),ctx=c.getContext('2d'),dpr=window.devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);const total=values.reduce((a,b)=>a+b,0),colors=['#8061f5','#5791fb','#f07bb8','#41cba0','#ffb45e','#8c9bf8','#b4a0ff'];if(!total){ctx.fillStyle='#888ba5';ctx.font='13px Arial';ctx.textAlign='center';ctx.fillText('No category data yet',w/2,h/2);return;}let start=-Math.PI/2;const cx=w*.34,cy=h*.48,r=Math.min(w*.24,h*.34),inner=r*.62;values.forEach((v,i)=>{const end=start+v/total*Math.PI*2;ctx.beginPath();ctx.arc(cx,cy,r,start,end);ctx.arc(cx,cy,inner,end,start,true);ctx.closePath();ctx.fillStyle=colors[i%colors.length];ctx.fill();start=end;});ctx.textAlign='center';ctx.fillStyle='#202044';ctx.font='bold 23px Arial';ctx.fillText(total,cx,cy+4);ctx.fillStyle='#8589a6';ctx.font='10px Arial';ctx.fillText('EVENTS',cx,cy+20);ctx.textAlign='left';ctx.font='11px Arial';labels.forEach((l,i)=>{const y=25+i*26;if(y<h-4){ctx.fillStyle=colors[i%colors.length];ctx.beginPath();ctx.arc(w*.66,y-3,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#626783';ctx.fillText(String(l).slice(0,15),w*.66+11,y);ctx.fillStyle='#222345';ctx.textAlign='right';ctx.fillText(values[i],w-5,y);ctx.textAlign='left';}})}
function renderCharts(){drawBarChart('regChart',monthlyLabels,monthlyValues);drawDonut('catChart',categoryLabels,categoryValues)}window.addEventListener('load',renderCharts);window.addEventListener('resize',renderCharts);
</script>
